#!/bin/bash
# Point the backend's URLs at the host ports (host-network mode) + recreate + verify
ssh -o BatchMode=yes -o ConnectTimeout=10 -i ~/.ssh/id_nura_clean root@72.61.71.211 'cd /docker/docsgpt/deployment && echo "=== before ===" && grep -E "DATABASE_URL|REDIS_URL|CELERY_BROKER" .env | sed "s|://[^@]*@|://***@|" | head -3 && sed -i "s|@postgres:5432|@127.0.0.1:5432|g; s|@redis:6379|@127.0.0.1:6379|g" .env && echo "=== after ===" && grep -E "DATABASE_URL|REDIS_URL|CELERY_BROKER" .env | sed "s|://[^@]*@|://***@|" | head -3 && docker compose -f docker-compose.yaml up -d --force-recreate backend 2>&1 | tail -1 && sleep 15 && echo "=== health ===" && curl -s -m 8 -o /dev/null -w "health: %{http_code}\n" http://127.0.0.1:7091/api/health 2>/dev/null && K=$(grep "^API_KEY=" .env | head -1 | cut -d= -f2) && echo "=== answer ===" && curl -s -m 45 -X POST http://127.0.0.1:7091/api/answer -H "Content-Type: application/json" -d "{\"question\":\"What is anatomy?\",\"api_key\":\"$K\"}" 2>/dev/null | head -c 400'
